mapper.select:
SELECT c.id, c.campaign_no, c.title, c.cover, c.creator_user_id, u.nickname AS creator_nickname, u.avatar AS creator_avatar, c.target_amount, c.raised_amount, c.support_count, cc.name AS category_name, c.status, c.end_time FROM qgc_campaign c LEFT JOIN qgc_user u ON c.creator_user_id = u.id LEFT JOIN qgc_campaign_category cc ON c.category_id = cc.id WHERE c.deleted = 0
AND c.creator_user_id = #{creatorUserId}
AND c.status = #{status}
AND c.category_id = #{categoryId}
AND c.title LIKE CONCAT('%', #{keyword}, '%')
ORDER BY c.create_time DESC
ORDER BY (c.raised_amount * 1.0 / c.target_amount) DESC, c.create_time DESC
ORDER BY RAND()
ORDER BY c.support_count DESC, c.raised_amount DESC
ORDER BY c.create_time DESC
